class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)
        MOD, B = 2147483647, 131
        h = [0] * (n + 1)
        p = [1] * (n + 1)
        for i, ch in enumerate(word):
            h[i + 1] = (h[i] * B + ord(ch)) % MOD
            p[i + 1] = p[i] * B % MOD
        def get(l, r):
            return (h[r] - h[l] * p[r - l]) % MOD
        t = 1
        while t * k < n:
            m = n - t * k
            if get(0, m) == get(m, n) and word[:m] == word[m:]:
                return t
            t += 1
        return (n + k - 1) // k

