class Solution {
public:
    int minimumTimeToInitialState(string word, int k) {
        int n = word.size();
        const long long MOD = 2147483647, B = 131;
        vector<long long> h(n + 1, 0), p(n + 1, 1);
        for (int i = 0; i < n; i++) {
            h[i + 1] = (h[i] * B + word[i]) % MOD;
            p[i + 1] = p[i] * B % MOD;
        }
        auto get = [&](int l, int r) { return ((h[r] - h[l] * p[r - l]) % MOD + MOD) % MOD; };
        int t = 1;
        while ((long long)t * k < n) {
            int m = n - t * k;
            if (get(0, m) == get(m, n) && word.compare(0, m, word, m) == 0) return t;
            t++;
        }
        return (n + k - 1) / k;
    }
};

