class Solution {
    public int minimumTimeToInitialState(String word, int k) {
        int n = word.length();
        long MOD = 2147483647, B = 131;
        long[] h = new long[n + 1], p = new long[n + 1];
        p[0] = 1;
        for (int i = 0; i < n; i++) {
            h[i + 1] = (h[i] * B + word.charAt(i)) % MOD;
            p[i + 1] = p[i] * B % MOD;
        }
        int t = 1;
        while ((long) t * k < n) {
            int m = n - t * k;
            long a = h[m], b = ((h[n] - h[m] * p[n - m]) % MOD + MOD) % MOD;
            if (a == b && word.substring(0, m).equals(word.substring(m))) return t;
            t++;
        }
        return (n + k - 1) / k;
    }
}

